    if value in config.STALL_RECOVERY_BAIL_REASON_TOKENS:
        return True
    if re.fullmatch(r"ci-local-unfixable:[A-Za-z0-9_,-]+", value):
        return True
    expanded = {
        "adopted-issue-closed", "adopted-issue-is-pr", "branch-create-failed", "ci-fix-exhausted",
